from wd_common import *
i=7
Z=lambda q,a:[('z',q),('b',a)]
def plant(c='#2f8a3a'): return '<path d="M0 0 v-50" stroke="#5a3a1a" stroke-width="4"/>'+''.join(f'<ellipse cx="{x}" cy="{y}" rx="9" ry="5" fill="{c}" transform="rotate({r} {x} {y})"/>' for x,y,r in [(-12,-20,-30),(12,-24,30),(-14,-36,-30),(14,-40,30),(0,-54,0),(-8,-48,-20),(8,-46,20)])
def katte(c='#2f8a3a'): return '<rect x="-34" y="-50" width="68" height="50" fill="#e9d6c0" stroke="#7a3b1f" stroke-width="3"/><rect x="-40" y="-56" width="80" height="8" fill="#c0392b"/>'+g(0,-56,1,plant(c))+'<rect x="-8" y="-34" width="16" height="16" fill="#3a1a0a"/>'
def beads(): return ''.join(f'<circle cx="{18*__import__("math").cos(k/18*6.28):.1f}" cy="{18*__import__("math").sin(k/18*6.28):.1f}" r="3" fill="#c9a66a"/>' for k in range(18))
fw=foreword(i,['In the courtyard of countless Hindu homes stands a small raised pot with a bushy plant: the <b>tulasī</b>, holy basil. Every evening a lamp is lit before it and the women of the house walk round it. Its leaves go into every worship of Viṣṇu, its wood becomes prayer beads, and once a year it is married to the Lord.',
 'This part explains the plant and its kinds, the tulasī platform, the daily worship, the story of Vṛndā, the wedding of Tulasī, the leaves in Viṣṇu’s worship, the rules for picking them, the beads, and what tulasī means.',
 'Previous: '+L('/why-do-we/namaskara/','namaskāra')+'. Next: '+L('/why-do-we/108/','108')+'. The Tulasī wedding falls in '+L('/festivals/kartika/','Kārtika')+'.'],Z('Is tulasī a goddess or a plant?','Both, says the tradition. A plant you water and a goddess you bow to.'))
gl=glance([('Plant','Holy basil, Ocimum tenuiflorum'),('Kinds','Kṛṣṇa tulasī (dark), Rāma tulasī (green)'),('Home','Tulasī kaṭṭe or vṛndāvana: a raised platform'),('Daily','Water in the morning, a lamp at dusk, circling'),('Goddess','Tulasī Devī, beloved of Viṣṇu'),('Story','Vṛndā, Jalandhara and Viṣṇu (versions differ)'),('Wedding','Tulasī vivāha in Kārtika, with Viṣṇu or the śāligrāma'),('In worship','Leaves essential in Viṣṇu and Kṛṣṇa worship'),('Beads','Tulasī mālā worn and used for japa'),('Meaning','Devotion, purity, the household’s guardian')],
 S('A woman lighting a lamp before a tulasī platform at dusk',g(280,215,2.2,katte())+g(160,215,1.5,person('#c0392b'))+g(220,200,.8,lamp()),'#20243a',215),Z('Does every home have one?','Many traditional homes do. City flats keep a pot on the balcony.'),'A goddess <b>in a pot</b>.')
plant_=reading('plant','THE PLANT','Holy basil',S('Two tulasī plants, one dark-leaved, one green',g(180,215,2.6,plant('#3a2a4a'))+g(380,215,2.6,plant('#3a9a4a'))+T(180,230,'Kṛṣṇa tulasī',11)+T(380,230,'Rāma tulasī',11),'#d8e8c8',230),
 ['<b>Holy basil.</b> Tulasī is <i>Ocimum tenuiflorum</i>, a fragrant herb related to sweet basil.','<b>Kṛṣṇa tulasī.</b> The dark, purple-leaved kind, named for Kṛṣṇa’s dark colour.','<b>Rāma tulasī.</b> The bright green kind.','<b>Fragrance.</b> Its strong scent is part of its place in worship.','<b>In medicine.</b> It is widely used in traditional remedies; this site does not give medical advice.'],Z('Can I grow it?','Sun, water, no frost. It is easy, and it will reward you.'),'A fragrant <b>sacred herb</b>.')
katte_=reading('katte','THE TULASĪ KAṬṬE','The platform in the courtyard',S('A decorated tulasī platform in a courtyard with kōlam drawn before it',g(280,200,2.4,katte())+''.join(f'<circle cx="{200+k*20}" cy="226" r="3" fill="#f4f1ea"/>' for k in range(9)),'#fff3cf',230),
 ['<b>Platform.</b> Tulasī is grown in a raised masonry platform, the <b>tulasī kaṭṭe</b> (Kannaḍa) or <b>vṛndāvana</b>.','<b>Place.</b> Often in the centre of the courtyard or in front of the house.','<b>Niche.</b> A small niche holds the lamp.','<b>Decoration.</b> Painted, marked with turmeric and kuṅkuma, with a kōlam or rangoli before it.','<b>Small homes.</b> A clay pot on a balcony serves the same purpose.'],Z('Why the courtyard?','It is the heart of the house, and the plant needs sun.'),'The heart <b>of the courtyard</b>.')
daily=reading('daily','DAILY WORSHIP','Water, lamp, circling',S('Morning: water poured; evening: lamp lit and the plant circled',g(150,215,1.8,katte())+g(90,215,1.2,person('#c0392b'))+'<path d="M110 150 q20 10 30 30" stroke="#4aa3df" stroke-width="4" fill="none"/>'+g(420,215,1.8,katte())+g(440,170,.6,lamp())+'<ellipse cx="420" cy="200" rx="70" ry="20" fill="none" stroke="#e0a800" stroke-width="3" stroke-dasharray="8 6"/>','#fff3cf',215),
 ['<b>Morning.</b> After bathing, water is poured at the plant’s root, often with a prayer.','<b>Dusk.</b> A lamp is lit before it at twilight.','<b>Circling.</b> The plant is circled, usually three or more times (see '+L('/why-do-we/pradakshina/','pradakṣiṇā')+').','<b>Women’s worship.</b> In many homes it is mainly kept by the women of the house.','<b>Marks.</b> Turmeric and kuṅkuma are applied to the platform.'],Z('Every single day?','Every day, in homes that keep it. It takes five minutes.'),'Water at dawn, <b>light at dusk</b>.')
vrinda=story('vrinda','THE STORY OF VṚNDĀ','How a devoted wife became tulasī',strip('Three panels: Vṛndā praying for her husband; Viṣṇu in disguise; Vṛndā becoming the tulasī plant',
 [('<rect width="144" height="190" fill="#fff3cf"/>'+g(72,180,.8,devi(sari='#2f8a3a',items=())),'#fff3cf'),
  ('<rect width="144" height="190" fill="#e3eaf3"/>'+g(50,180,.7,devi(sari='#2f8a3a',items=()))+g(105,180,.7,god('#1d4f8a')),'#e3eaf3'),
  ('<rect width="144" height="190" fill="#d8e8c8"/>'+g(72,180,1.4,plant()),'#d8e8c8')],['her vow','the disguise','the plant']),'A Purāṇic story; versions in the Padma, Devī Bhāgavata and other Purāṇas differ.',
 ['<b>Vṛndā</b> was the faithful wife of the asura <b>Jalandhara</b>; her devotion made him unbeatable, even by the gods.','To end his tyranny, Viṣṇu took Jalandhara’s form and broke her vow; Jalandhara was then defeated.','Vṛndā cursed Viṣṇu to become a stone (the śāligrāma) and gave up her life; Viṣṇu blessed her to be worshipped as tulasī and to be dear to him forever.'])
wed=reading('vivaha','TULASĪ VIVĀHA','The wedding of the plant',S('A tulasī platform dressed as a bride, a śāligrāma and Kṛṣṇa image beside it, sugarcane arch',g(280,215,2,katte())+'<path d="M180 220 q100 -200 200 0" stroke="#7aa86a" stroke-width="8" fill="none"/>'+g(380,215,1,god('#1d4f8a'))+g(330,215,.7,'<ellipse rx="10" ry="12" cy="-12" fill="#2a2a2a"/>'),'#20243a',230),
 ['<b>When.</b> In the month of Kārtika, on or around the twelfth day of the bright half (Utthāna Dvādaśī) when Viṣṇu wakes from his sleep. (Days vary by region.)','<b>The groom.</b> Tulasī is married to Viṣṇu, Kṛṣṇa or the śāligrāma stone.','<b>Like a real wedding.</b> The plant is dressed as a bride; a canopy of sugarcane is set up; songs, garlands and a feast follow.','<b>Karnataka.</b> Kept in many homes as Tulasī habba, with lamps and gooseberry branches.','<b>Season.</b> It marks the start of the wedding season in many communities. See '+L('/festivals/kartika/','Kārtika')+'.'],Z('A wedding for a plant?','For the goddess in the plant. And for the family, a festival.'),'The goddess <b>marries the Lord</b>.')
leaves=reading('leaves','IN VIṢṆU’S WORSHIP','No pūjā without a leaf',S('A plate of tulasī leaves offered at the feet of Kṛṣṇa',g(280,215,1.8,god('#1d4f8a'))+''.join(f'<ellipse cx="{240+k*14}" cy="210" rx="7" ry="4" fill="#2f8a3a"/>' for k in range(6)),'#e3eaf3',215),
 ['<b>Essential.</b> Tulasī leaves are offered in the worship of Viṣṇu, Kṛṣṇa and their forms; many say naivedya to Viṣṇu is incomplete without one.','<b>On the food.</b> A leaf is placed on the food offering before it is offered.','<b>In tīrtha.</b> Tulasī is added to the holy water in Vaiṣṇava temples.','<b>Not for every god.</b> By common belief, tulasī is not offered to Gaṇeśa. (Tradition, linked to a story.)','<b>Garlands.</b> Kṛṣṇa’s idols wear tulasī garlands, as at '+L('/tulunadu/temples/udupi-srikrishna/','Uḍupi')+'.'],Z('Why not to Gaṇeśa?','A story of a quarrel and a curse. The custom stands.'),'Viṣṇu’s <b>favourite leaf</b>.')
rules=reading('picking','PICKING THE LEAVES','When and how',S('A hand picking a few leaves gently from the top; a sun and moon',g(280,215,2.6,plant())+'<path d="M330 90 l-40 20" stroke="#e8c3a0" stroke-width="7"/>'+g(120,60,1,'<circle r="18" fill="#f0c030"/>')+g(460,60,1,moon()),'#fff3cf',215),
 ['<b>With respect.</b> Leaves are picked gently, after bathing, often with a prayer asking permission.','<b>Not at night.</b> By common custom, tulasī is not picked after sunset.','<b>Certain days.</b> Many avoid picking on dvādaśī and some other days; leaves are gathered the day before. (Customs vary.)','<b>Reusable.</b> A tulasī leaf offered once may be washed and offered again, it is said. (Tradition.)','<b>Never thrown.</b> Dried leaves are put in water or the earth, not in the rubbish.'],Z('So many rules for a leaf?','It is a goddess, remember. You would ask before you took.'),'Ask <b>before you pick</b>.')
mala=reading('mala','TULASĪ BEADS','The mālā of the Vaiṣṇavas',S('A string of tulasī beads, one around a neck, one in a hand for japa',g(160,140,3,beads())+g(400,215,1.6,person('#f4f1ea'))+g(400,150,.8,beads()),'#fff3cf',215),
 ['<b>Beads.</b> The woody stem of tulasī is cut into beads for prayer strings (japa mālā).','<b>Worn.</b> Many Vaiṣṇavas wear a tulasī necklace (kaṇṭhī) as a sign of devotion.','<b>Japa.</b> The mālā is used to count the Lord’s names, often 108 times (see '+L('/why-do-we/108/','Part 9')+').','<b>Śaivas.</b> Śaivas use rudrākṣa instead.','<b>Care.</b> Mālās are kept clean and treated with respect.'],Z('Can anyone wear one?','Traditions differ; many teachers give it at initiation.'),'Counting <b>on the goddess’s wood</b>.')
death=reading('last','AT THE END OF LIFE','A leaf for the dying',S('A small brass vessel of water with a tulasī leaf in it',g(280,215,3,'<path d="M-12 0 h24 l-4 -24 h-16z" fill="#c9a227"/>'+'<ellipse cx="2" cy="-26" rx="6" ry="3" fill="#2f8a3a"/>'),'#e3eaf3',215),
 ['<b>Last water.</b> By tradition, water with a tulasī leaf, often Gaṅgā water, is placed on the lips of the dying.','<b>Peace.</b> It is believed to bring the presence of Viṣṇu at the last moment. (Belief.)','<b>Final rites.</b> Tulasī leaves are used in funeral and ancestral rites in many communities.','<b>Comfort.</b> For families it is a simple act of love.','<b>See.</b> '+L('/festivals/pitru-paksha/','Pitṛ Pakṣa')+'.'],Z('Why at the end?','The plant dear to Viṣṇu goes with the soul to Viṣṇu.'),'A leaf <b>for the last journey</b>.')
mean=reading('meaning','WHAT IT MEANS','Devotion that grows',S('A tulasī plant glowing at the centre of a home',g(280,200,1.4,ainmane(220) if False else '<rect x="-150" y="-80" width="300" height="80" fill="#e9d6c0"/><path d="M-170 -80 L0 -140 L170 -80z" fill="#7a3b1f"/>')+g(280,215,1.4,katte())+'<circle cx="280" cy="150" r="60" fill="#e0a800" opacity=".18"/>','#20243a',215),
 ['<b>Devotion.</b> Vṛndā’s faithfulness is honoured in the plant: tulasī stands for single-minded devotion. (Interpretation.)','<b>Household guardian.</b> The tulasī in the courtyard is seen as the protecting goddess of the home.','<b>Daily discipline.</b> Watering and lighting it every day keeps worship in the rhythm of the house.','<b>Living worship.</b> Unlike an image, the plant grows, flowers and needs care: a living goddess. (Interpretation.)','<b>Nature.</b> Many see in it the Hindu reverence for plants and the earth.'],Z('A goddess that needs watering?','The best kind: you look after her, she looks after you.'),'Look after her, <b>she looks after you</b>.')
endp=end(i,['<b>Plant.</b> Holy basil; Kṛṣṇa and Rāma tulasī.','<b>Home.</b> The tulasī kaṭṭe; water at dawn, lamp at dusk, circling.','<b>Story.</b> Vṛndā, Jalandhara, Viṣṇu and the śāligrāma.','<b>Festival.</b> Tulasī vivāha in Kārtika.','<b>Worship.</b> Essential in Viṣṇu’s pūjā; beads for japa; a leaf for the dying.'],'Part 9 is the number 108.','A goddess in a pot')
src=sources([('Tulasī:','Wikipedia, “Tulsi in Hinduism” (kinds, vṛndāvana, daily worship, Vṛndā and Jalandhara in the Purāṇas, Tulasī vivāha, use in Viṣṇu worship, mālā, last rites), “Ocimum tenuiflorum”; household practice in Karnataka (tulasī kaṭṭe, Tulasī habba).')],'the Vṛndā story differs by Purāṇa (some name the plant’s origin differently); the Gaṇeśa custom, picking days and reuse of leaves are traditions that vary; no medical claims are made.','No verse text is reproduced in this part.')
finish(i,'PART 8 OF 10 · KAṬṬE · VṚNDĀ · VIVĀHA',covart('A tulasī platform with a lamp at dusk',g(220,190,1.8,katte())+g(250,150,.6,lamp())),'A goddess in a pot',
 'Why we worship <b>tulasī</b>: the plant, the tulasī kaṭṭe, the daily lamp, the story of <b>Vṛndā</b>, the <b>Tulasī vivāha</b>, leaves in Viṣṇu’s worship, picking rules, beads and the last rites.',
 'Why do we worship tulasī? Explained and illustrated: holy basil, Kṛṣṇa and Rāma tulasī, tulasī kaṭṭe, daily worship, Vṛndā and Jalandhara, Tulasī vivāha in Kārtika, leaves in Viṣṇu worship, picking customs, tulasī mālā and meaning.',
 [fw,gl,plant_,katte_,daily,vrinda,wed,leaves,rules,mala,death,mean,endp,src])
